// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListChallenges List challenges
	// (GET /api/v1/challenges)
	ListChallenges(ctx context.Context, request ListChallengesRequestObject) (ListChallengesResponseObject, error)
	// CreateChallenge Create a challenge
	// (POST /api/v1/challenges)
	CreateChallenge(ctx context.Context, request CreateChallengeRequestObject) (CreateChallengeResponseObject, error)
	// DeleteChallenge Delete a challenge
	// (DELETE /api/v1/challenges/{challengeId})
	DeleteChallenge(ctx context.Context, request DeleteChallengeRequestObject) (DeleteChallengeResponseObject, error)
	// GetChallenge Read a challenge
	// (GET /api/v1/challenges/{challengeId})
	GetChallenge(ctx context.Context, request GetChallengeRequestObject) (GetChallengeResponseObject, error)
	// UpdateChallenge Edit the title and the description
	// (PATCH /api/v1/challenges/{challengeId})
	UpdateChallenge(ctx context.Context, request UpdateChallengeRequestObject) (UpdateChallengeResponseObject, error)
	// AbandonChallenge Abandon a challenge
	// (POST /api/v1/challenges/{challengeId}/abandon)
	AbandonChallenge(ctx context.Context, request AbandonChallengeRequestObject) (AbandonChallengeResponseObject, error)
	// AddCreator Add a creator
	// (POST /api/v1/challenges/{challengeId}/creators)
	AddCreator(ctx context.Context, request AddCreatorRequestObject) (AddCreatorResponseObject, error)
	// JoinChallenge Join a challenge
	// (POST /api/v1/challenges/{challengeId}/join)
	JoinChallenge(ctx context.Context, request JoinChallengeRequestObject) (JoinChallengeResponseObject, error)
	// ExcludeParticipant Exclude a participant
	// (DELETE /api/v1/challenges/{challengeId}/participants/{userId})
	ExcludeParticipant(ctx context.Context, request ExcludeParticipantRequestObject) (ExcludeParticipantResponseObject, error)
	// GetMe Read my profile
	// (GET /api/v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// PatchMe Update my profile
	// (PATCH /api/v1/me)
	PatchMe(ctx context.Context, request PatchMeRequestObject) (PatchMeResponseObject, error)
	// GetSports List the sports
	// (GET /api/v1/sports)
	GetSports(ctx context.Context, request GetSportsRequestObject) (GetSportsResponseObject, error)
	// GetHealthz Liveness probe
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// GetReadyz Readiness probe
	// (GET /readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

